create table refill_policies (auto_generate_enabled bit not null, hysteresis_percent float(53) not null, low_level_percent float(53) not null, policy_version integer not null, target_level_percent float(53) not null, version integer not null, created_at datetime(6) not null, fuel_product_id bigint, id bigint not null auto_increment, organization_id bigint not null, provider_id bigint, tank_id bigint not null, updated_at datetime(6) not null, primary key (id)) engine=InnoDB;
alter table refill_policies add constraint uk_refill_policies_tank unique (tank_id);
create table refill_episodes (opened_level float(53) not null, opened_level_percent float(53) not null, policy_version integer not null, request_emitted bit not null, requested_volume float(53) not null, target_level float(53) not null, version integer not null, closed_at datetime(6), closed_level_percent float(53), created_at datetime(6) not null, id bigint not null auto_increment, open_slot bigint, opened_at datetime(6) not null, organization_id bigint not null, request_id bigint, tank_id bigint not null, updated_at datetime(6) not null, episode_key varchar(160) not null, unit varchar(20) not null, status VARCHAR(20) not null, primary key (id)) engine=InnoDB;
alter table refill_episodes add constraint uk_refill_episodes_episode_key unique (episode_key);
alter table refill_episodes add constraint uk_refill_episodes_open_slot unique (open_slot);
